#!/usr/bin/env bash
# Flash info : les messages du ruban ne s'appellent plus « actualités » (tableau de bord, ruban, panneau public, tuto, fiche).
# Prérequis : apply-docs-tutos-admin.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-flash-info.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/app-shell/ControlPanelSidebar.tsx" 2>/dev/null | grep -qF "label: \"Flash info\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Deux mots se croisent dans le projet" "apps/web/content/docs/dev/etude-de-cas/un-tutoriel-en-donnees.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-tutos-admin.sh"; exit 1; }
